document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const feedback=document.querySelector('#copy-feedback');try{await navigator.clipboard.writeText(button.dataset.copy);feedback.textContent=button.dataset.copy+' copied.';button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1600)}catch{feedback.textContent='Copy was blocked by your browser. Select the complete code and copy it manually.'}}));